#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> L(n), C(n);
    for (int i = 0; i < n; ++i) cin >> L[i];
    for (int i = 0; i < n; ++i) cin >> C[i];

    vector<vector<int>> adj(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // 求中位数 T
    vector<int> sortedL = L;
    sort(sortedL.begin(), sortedL.end());
    int T = sortedL[n / 2];

    vector<ll> f(n), ans(n);

    // 向下 DFS 计算 f
    function<void(int,int)> dfs1 = [&](int u, int p) {
        f[u] = C[u];
        for (int v : adj[u]) {
            if (v == p) continue;
            dfs1(v, u);
            f[u] += min(0LL, f[v]);
        }
    };

    // 换根 DFS 计算 ans
    function<void(int,int)> dfs2 = [&](int u, int p) {
        if (p == -1) ans[u] = f[u];
        for (int v : adj[u]) {
            if (v == p) continue;
            ll without_v = ans[u] - min(0LL, f[v]);
            ll res = C[v];
            for (int w : adj[v]) {
                if (w == u) continue;
                res += min(0LL, f[w]);
            }
            res += min(0LL, without_v);
            ans[v] = res;
            dfs2(v, u);
        }
    };

    dfs1(0, -1);
    dfs2(0, -1);

    ll total = 0;
    for (int i = 0; i < n; ++i) {
        total += ll(abs(L[i] - T)) * ans[i];
    }
    cout << total;

    return 0;
}
